        spinSpeedX: 1.0
      });

      // 3. Initialize Grid Canvas instances
      const bronzeCanvas = document.querySelector('.edition[data-edition="bronze"] .edition-canvas');
      const silverCanvas = document.querySelector('.edition[data-edition="silver"] .edition-canvas');
      const goldCanvas   = document.querySelector('.edition[data-edition="gold"] .edition-canvas');
      const blackCanvas  = document.querySelector('.edition[data-edition="black"] .edition-canvas');

      editionRenderers.bronze = new CoinRenderer(bronzeCanvas, textures.front, textures.back, {
        baseColor: [0.75, 0.40, 0.20], // Warm bronze
        roughness: 0.32,
        spinSpeedY: 1.0,
        spinSpeedX: 0.0 // Unique rotation signature
      });

      editionRenderers.silver = new CoinRenderer(silverCanvas, textures.front, textures.back, {
        baseColor: [0.82, 0.84, 0.88], // Brilliant Sterling
        roughness: 0.08,
        spinSpeedY: 1.0,
        spinSpeedX: 1.0
      });

      editionRenderers.gold = new CoinRenderer(goldCanvas, textures.front, textures.back, {
        baseColor: [0.95, 0.75, 0.15], // Rich Gold
        roughness: 0.15,
        spinSpeedY: 1.0,
        spinSpeedX: 1.0
      });

      editionRenderers.black = new CoinRenderer(blackCanvas, textures.front, textures.back, {
        baseColor: [0.12, 0.12, 0.14], // Ultra dark obsidian
        roughness: 0.04, // Extremely shiny glassy surface
        spinSpeedY: 1.0,
        spinSpeedX: 1.0
      });

      // Start main loop
      startTime = performance.now();
      play();
    });

    /* Animation Loop Controls */
    function tick(timestamp) {
      if (isPaused) return;
      const elapsed = timestamp - startTime;
      const loopPeriod = 8000; // Complete rotation loop cycle takes 8 seconds
      const t = (elapsed % loopPeriod) / loopPeriod;

      // Update hero
      if (heroRenderer) heroRenderer.render(t);

      // Render grid items with slight time offsets to make grid feel alive and staggered
      if (editionRenderers.bronze) editionRenderers.bronze.render((t + 0.1) % 1.0);
      if (editionRenderers.silver) editionRenderers.silver.render((t + 0.3) % 1.0);
      if (editionRenderers.gold)   editionRenderers.gold.render((t + 0.6) % 1.0);
      if (editionRenderers.black)  editionRenderers.black.render((t + 0.8) % 1.0);

      animationFrameId = requestAnimationFrame(tick);
    }

    function pause() {
      isPaused = true;
      if (animationFrameId) {
        cancelAnimationFrame(animationFrameId);
        animationFrameId = null;
      }
    }

    function play() {
      isPaused = false;
      startTime = performance.now() - (startTime ? (performance.now() - startTime) % 8000 : 0);
      animationFrameId = requestAnimationFrame(tick);
    }

    /* Programmatic Grading API Setup */
    window.demo = {
      canvas: document.getElementById('coin-hero'),
      setTime(t) {
        // Enforce synchronous rendering for evaluation frame
        if (heroRenderer) {
          heroRenderer.render(t);
        }
        if (editionRenderers.bronze) editionRenderers.bronze.render((t + 0.1) % 1.0);
        if (editionRenderers.silver) editionRenderers.silver.render((t + 0.3) % 1.0);
        if (editionRenderers.gold)   editionRenderers.gold.render((t + 0.6) % 1.0);
        if (editionRenderers.black)  editionRenderers.black.render((t + 0.8) % 1.0);
      },
      pause() {
        pause();
      }
    };
  </script>
